// ===== NODE 5: Tính điểm năng suất cho từng thành viên =====
const data = $input.first().json;
const members = data.members || [];
const teamAvg = data.team_averages || {};
const period = data.period || {};

const scoredMembers = members.map(member => {
  const m = member.metrics;

  // === 1. COMPLETION SCORE (0-100) ===
  // Dựa trên số task hoàn thành, so sánh với team average
  let completionScore = 0;
  if (m.tasks_completed > 0) {
    const completionRatio = teamAvg.avg_completed > 0
      ? m.tasks_completed / teamAvg.avg_completed
      : 1;
    completionScore = Math.min(100, Math.round(completionRatio * 60 + 20));
  }
  // Bonus nếu hoàn thành nhiều hơn trung bình
  if (m.tasks_completed > teamAvg.avg_completed && teamAvg.avg_completed > 0) {
    completionScore = Math.min(100, completionScore + 10);
  }

  // === 2. TIMELINESS SCORE (0-100) ===
  // Dựa trên tỷ lệ task đúng hạn vs quá hạn
  let timelinessScore = 80; // default nếu chưa có task
  const totalWithDeadline = m.tasks_on_time + m.tasks_overdue;
  if (totalWithDeadline > 0) {
    const onTimeRate = m.tasks_on_time / totalWithDeadline;
    timelinessScore = Math.round(onTimeRate * 100);
  } else if (m.tasks_completed > 0) {
    timelinessScore = 70; // completed nhưng không có deadline
  }

  // === 3. VELOCITY SCORE (0-100) ===
  // Dựa trên story points hoàn thành, so sánh với team
  let velocityScore = 0;
  if (m.total_story_points > 0) {
    const velocityRatio = teamAvg.avg_story_points > 0
      ? m.total_story_points / teamAvg.avg_story_points
      : 1;
    velocityScore = Math.min(100, Math.round(velocityRatio * 60 + 20));
  }
  // Bonus cho lead time nhanh
  if (m.avg_lead_time_hours !== null && m.avg_lead_time_hours < 48) {
    velocityScore = Math.min(100, velocityScore + 10);
  }

  // === 4. QUALITY SCORE (0-100) ===
  // Dựa trên stuck tasks, bottleneck (ít hơn = tốt hơn)
  let qualityScore = 100;
  // Trừ điểm cho stuck tasks
  qualityScore -= m.stuck_task_count * 15;
  // Trừ điểm cho bottleneck
  qualityScore -= m.bottleneck_count * 20;
  // Trừ điểm cho task quá hạn
  qualityScore -= m.tasks_overdue * 10;
  qualityScore = Math.max(0, Math.min(100, qualityScore));

  // === FINAL SCORE (0-200, tương thích members.productivity_score) ===
  // Trọng số: completion=30%, timeliness=25%, velocity=25%, quality=20%
  const weightedScore = (
    completionScore * 0.30 +
    timelinessScore * 0.25 +
    velocityScore * 0.25 +
    qualityScore * 0.20
  );
  // Scale lên 0-200
  const finalScore = Math.round(weightedScore * 2 * 100) / 100;

  // === GRADE ===
  let grade = 'C';
  if (finalScore >= 180) grade = 'A+';
  else if (finalScore >= 160) grade = 'A';
  else if (finalScore >= 140) grade = 'B+';
  else if (finalScore >= 120) grade = 'B';
  else if (finalScore >= 100) grade = 'C+';
  else if (finalScore >= 80) grade = 'C';
  else if (finalScore >= 60) grade = 'D';
  else grade = 'F';

  // === TREND ===
  let trend = 'STABLE';
  if (member.previous_score) {
    const diff = finalScore - member.previous_score.final_score;
    if (diff >= 10) trend = 'IMPROVING';
    else if (diff <= -10) trend = 'DECLINING';
  }

  return {
    member_id: member.member_id,
    full_name: member.full_name,
    email: member.email,
    current_db_score: member.current_score,
    period_start: period.start,
    period_end: period.end,
    // Metrics thô
    tasks_completed: m.tasks_completed,
    tasks_overdue: m.tasks_overdue,
    tasks_on_time: m.tasks_on_time,
    total_story_points: m.total_story_points,
    avg_lead_time_hours: m.avg_lead_time_hours,
    stuck_task_count: m.stuck_task_count,
    bottleneck_count: m.bottleneck_count,
    active_task_count: m.active_task_count,
    activity_count: m.activity_count,
    // Điểm thành phần
    completion_score: completionScore,
    timeliness_score: timelinessScore,
    velocity_score: velocityScore,
    quality_score: qualityScore,
    // Kết quả
    final_score: finalScore,
    score_grade: grade,
    score_trend: trend,
    previous_score: member.previous_score
  };
});

// Sắp xếp theo điểm giảm dần
scoredMembers.sort((a, b) => b.final_score - a.final_score);

return [{
  json: {
    total_members: scoredMembers.length,
    period: period,
    team_averages: teamAvg,
    scored_members: scoredMembers
  }
}];

// ===== NODE 6: Chuẩn bị prompt cho AI phân tích =====
const data = $input.first().json;
const members = data.scored_members;
const period = data.period;
const teamAvg = data.team_averages;

let context = '=== BÁO CÁO NĂNG SUẤT THÀNH VIÊN ===\n';
context += `Kỳ đánh giá: ${period.start} đến ${period.end} (${period.days} ngày)\n`;
context += `Team trung bình: ${teamAvg.avg_completed} tasks hoàn thành, ${teamAvg.avg_story_points} story points\n\n`;

members.forEach((m, i) => {
  context += `--- ${i+1}. ${m.full_name} (${m.email}) ---\n`;
  context += `  Điểm tổng: ${m.final_score}/200 (${m.score_grade}) | Trend: ${m.score_trend}\n`;
  context += `  Tasks hoàn thành: ${m.tasks_completed} | Đúng hạn: ${m.tasks_on_time} | Quá hạn: ${m.tasks_overdue}\n`;
  context += `  Story points: ${m.total_story_points} | Lead time TB: ${m.avg_lead_time_hours || 'N/A'} giờ\n`;
  context += `  Stuck tasks: ${m.stuck_task_count} | Bottleneck: ${m.bottleneck_count} | Active: ${m.active_task_count}\n`;
  context += `  Điểm thành phần: Completion=${m.completion_score}, Timeliness=${m.timeliness_score}, `;
  context += `Velocity=${m.velocity_score}, Quality=${m.quality_score}\n`;
  if (m.previous_score) {
    context += `  Kỳ trước: ${m.previous_score.final_score} (${m.previous_score.score_grade})\n`;
  }
  context += '\n';
});

const prompt = `Bạn là AI chuyên gia đánh giá năng suất đội ngũ phát triển phần mềm.

Dựa trên dữ liệu thực tế sau, hãy viết nhận xét ngắn gọn cho TỪNG thành viên.

${context}

Hãy trả về JSON array, mỗi phần tử cho 1 thành viên, theo format SAU (KHÔNG thêm markdown, KHÔNG thêm text ngoài JSON):

[
  {
    "member_id": "uuid",
    "summary": "Nhận xét tổng quan 2-3 câu về hiệu suất, điểm mạnh, điểm cần cải thiện (tiếng Việt)",
    "strengths": ["Điểm mạnh 1", "Điểm mạnh 2"],
    "improvements": ["Cần cải thiện 1", "Cần cải thiện 2"],
    "recommendation": "Đề xuất hành động cụ thể tiếp theo"
  }
]

Lưu ý:
- Mỗi member phải có 1 entry
- summary phải dựa trên dữ liệu thực tế, không chung chung
- Trả về JSON array THUẦN TÚY, không có markdown code block`;

return [{
  json: {
    prompt: prompt,
    scored_members: members,
    period: period,
    team_averages: teamAvg
  }
}];

