// ===== NODE 10: Split members thành individual items =====
const data = $input.first().json;
const members = data.merged_members;
const period = data.period;

const items = members.map(m => ({
  json: {
    member_id: m.member_id,
    period_start: m.period_start || period.start,
    period_end: m.period_end || period.end,
    tasks_completed: m.tasks_completed,
    tasks_overdue: m.tasks_overdue,
    tasks_on_time: m.tasks_on_time,
    total_story_points: m.total_story_points,
    avg_lead_time_hours: m.avg_lead_time_hours,
    stuck_task_count: m.stuck_task_count,
    bottleneck_count: m.bottleneck_count,
    active_task_count: m.active_task_count,
    completion_score: m.completion_score,
    timeliness_score: m.timeliness_score,
    velocity_score: m.velocity_score,
    quality_score: m.quality_score,
    final_score: m.final_score,
    score_grade: m.score_grade,
    score_trend: m.score_trend,
    ai_summary: m.ai_summary,
    ai_raw_response: m.ai_raw_response,
    metadata: {
      source: 'n8n_flow8',
      parse_success: m.parse_success,
      full_name: m.full_name,
      email: m.email,
      scored_at: new Date().toISOString()
    }
  }
}));

return items;

// ===== NODE 16: Tổng hợp kết quả cuối cùng =====
const savedResults = $input.all();
const scoreData = $('Code - Calculate Scores').first().json;
const parseData = $('Code - Parse AI & Merge').first().json;

const successCount = savedResults.filter(r => r.json.id || r.json.member_id).length;
const errorCount = savedResults.filter(r => r.json.error).length;

// Phân loại kết quả
const gradeCounts = {};
const trendCounts = { IMPROVING: 0, STABLE: 0, DECLINING: 0 };

savedResults.forEach(r => {
  const grade = r.json.score_grade;
  if (grade) gradeCounts[grade] = (gradeCounts[grade] || 0) + 1;
  const trend = r.json.score_trend;
  if (trend && trendCounts.hasOwnProperty(trend)) trendCounts[trend]++;
});

return [{
  json: {
    success: true,
    flow: 'flow8-member-productivity-scoring',
    summary: {
      total_members_scored: successCount,
      save_errors: errorCount,
      ai_parse_success: parseData.parse_success,
      grade_distribution: gradeCounts,
      trend_distribution: trendCounts,
      period: scoreData.period,
      team_averages: scoreData.team_averages
    },
    scored_members: savedResults.map(r => ({
      member_id: r.json.member_id,
      full_name: r.json.metadata?.full_name,
      final_score: r.json.final_score,
      score_grade: r.json.score_grade,
      score_trend: r.json.score_trend
    })),
    processed_at: new Date().toISOString()
  }
}];

// ===== No Members Found =====
return [{
  json: {
    success: true,
    flow: 'flow8-member-productivity-scoring',
    message: 'Không có thành viên nào để chấm điểm. Database có thể trống.',
    total_members: 0,
    scanned_at: new Date().toISOString()
  }
}];

// ===== No Valid Scored Members =====
return [{
  json: {
    success: false,
    flow: 'flow8-member-productivity-scoring',
    message: 'Không có dữ liệu chấm điểm hợp lệ sau khi xử lý AI.',
    scanned_at: new Date().toISOString()
  }
}];

// ===== Global Error Handler =====
const errorData = $input.first().json;

const errorMessage = errorData.execution?.error?.message ||
                     errorData.error?.message ||
                     'Unknown error in Flow 8';
const errorNode = errorData.execution?.lastNodeExecuted || 'unknown';

console.error(`[Flow 8 Error] Node: ${errorNode}, Error: ${errorMessage}`);

return [{
  json: {
    success: false,
    flow: 'flow8-member-productivity-scoring',
    error: {
      message: errorMessage,
      node: errorNode,
      timestamp: new Date().toISOString()
    }
  }
}];
